1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = QuoteResult | ClaimResult;
37	
38	export interface QuoteResult {
39	  premium: number;
40	}
41	
42	export interface ClaimResult {
43	  payout: number;
44	  remainingCap: number;
45	}
46	
47	export interface ScenarioResult {
48	  results: Result[];
49	}
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
53	const BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	};
60	
61	const policyBasePremium = (items: Item[]): number =>
62	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
63	
64	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
65	// separate term rather than folded into a `base * 1.1` factor, which is not
66	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
67	const quotePremium = (items: Item[]): number => {
68	  const base = policyBasePremium(items);
69	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE);
70	};
71	
72	const quote = (step: QuoteStep): QuoteResult => ({
73	  premium: quotePremium(step.items),
74	});
75	
76	const runStep = (step: Step): Result => {
77	  switch (step.op) {
78	    case "quote":
79	      return quote(step);
80	    default:
81	      throw new Error(`unsupported step: ${step.op}`);
82	  }
83	};
84	
85	export const runScenario = (scenario: Scenario): ScenarioResult => ({
86	  results: scenario.steps.map(runStep),
87	});
88

